class Context:
    @t.overload
    def invoke(self, a: int) -> int: ...

    @t.overload
    def invoke(self, a: str) -> str: ...

    def invoke(self, a):
        """Invoke the callback."""
        return a

    @property
    def name(self):
        return 'x'

    @name.setter
    def name(self, v):
